import csv, statistics
files={'Death':'ae_death_by_year.csv','CI':'ae_ci_by_year.csv','TPD':'ae_tpd_by_year.csv','IP':'ae_ip_by_year.csv'}
for b,fn in files.items():
    with open(fn) as f:
        r=csv.DictReader(f)
        rows=[]
        for row in r:
            y=None; ae=None
            for k,v in row.items():
                kk=k.strip().lower()
                if kk in ('year','fy'): y=int(v)
                elif kk in ('ae','a/e','ae_ratio','ratio'): ae=float(v)
            if y is not None and ae is not None: rows.append((y,ae))
    rows.sort()
    moves=[]
    for i in range(1,len(rows)):
        y=rows[i][0]; move=rows[i][1]-rows[i-1][1]
        moves.append((y,move,abs(move)))
    med=statistics.median([m[2] for m in moves])
    print(b, 'median_abs_move=', round(med,5))
    for y,m,am in moves:
        flag = am > 2.5*med if med>0 else False
        print(f'  {y}: move={m:+.4f} abs={am:.4f} flag={flag}')
    flags=[y for y,m,am in moves if (med>0 and am>2.5*med)]
    print(b, 'flag_years=', flags)
# termination check maybe
with open('ae_ip_termination.csv') as f:
    r=csv.DictReader(f)
    print('termination rows:')
    for row in r:
        print(row)
